import{_ as n,a0 as p,w as d,s as c,ao as o,I as i,x as e,a1 as a,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"如何在 Linux 中使用 SCP 安全地傳輸文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中使用 SCP 安全地傳輸文件 | LCTT (202212) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中使用 SCP 安全地傳輸文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中使用 SCP 安全地傳輸文件 | LCTT (202212) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202212/20221103.6 ⭐️⭐️⭐️ How To Securely Transfer Files With SCP In Linux","title":"如何在 Linux 中使用 SCP 安全地傳輸文件","tag":"202212","desc":""},"relativePath":"202212/20221103.6 ⭐️⭐️⭐️ How To Securely Transfer Files With SCP In Linux.md","filePath":"[post].md"}'),h={name:"202212/20221103.6 ⭐️⭐️⭐️ How To Securely Transfer Files With SCP In Linux.md"};function r(g,s,k,b,u,m){const t=p("Link");return d(),c("div",null,[s[34]||(s[34]=o('<h1 id="如何在-linux-中使用-scp-安全地傳輸文件" tabindex="-1">如何在 Linux 中使用 SCP 安全地傳輸文件 <a class="header-anchor" href="#如何在-linux-中使用-scp-安全地傳輸文件" aria-label="Permalink to “如何在 Linux 中使用 SCP 安全地傳輸文件”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202212/24/152224vy4glx9x39mtth9b.jpg" alt=""></p><p>在網絡上文件傳輸可以通過各種不同的方式和協議來完成。<strong>遠程複製文件</strong>最常用的協議是 <strong>Rsync</strong>、<strong>SCP</strong> 和 <strong>SFTP</strong>。在本文中，我們將瞭解<strong>什麼是 SCP</strong> 以及如何在 Linux 和類 Unix 操作系統中<strong>使用 SCP 在本地和遠程計算機之間安全地傳輸文件</strong>。</p><h3 id="什麼是-scp" tabindex="-1">什麼是 SCP？ <a class="header-anchor" href="#什麼是-scp" aria-label="Permalink to “什麼是 SCP？”">​</a></h3><p>SCP，代表 <ruby>安全複製<rt>Secure Copy</rt></ruby>，它是一個命令列程序，在 Linux 和類 Unix 操作系統中以安全的方式在本地和遠程系統之間，或在兩個遠程系統之間複製文件和目錄。</p><p>使用 <code>scp</code> 命令，你可以安全地複製文件或目錄：</p><ul><li>從本地到遠程系統</li><li>從遠程系統到本地</li><li>在兩個遠程系統之間</li></ul><p>使用 <code>scp</code> 命令傳輸數據時，文件和目錄都是加密的。因此，即使網絡被破壞，作惡者也無法獲得任何有意義的數據。</p><p>SCP 是 openSSH 程序的一個組件，它使用 SSH 協議安全地傳輸文件。幾乎所有現代 Linux 和 Unix 發行版都預裝了 OpenSSH，所以不必費心安裝它。</p><h4 id="提醒一句" tabindex="-1">提醒一句： <a class="header-anchor" href="#提醒一句" aria-label="Permalink to “提醒一句：”">​</a></h4><p>根據 openSSH 開發人員的<strong>官方公告</strong>：</p>',11)),i("blockquote",null,[s[2]||(s[2]=i("p",null,[i("strong",null,"scp 協議已經過時了"),e("，它不靈活且不易修復。我們建議使用更現代的協議，如 "),i("code",null,"sftp"),e(" 和 "),i("code",null,"rsync"),e(" 來代替。")],-1)),i("p",null,[s[1]||(s[1]=e("參考 - ",-1)),a(t,{href:"https://lists.mindrot.org/pipermail/openssh-unix-dev/2019-March/037672.html"},{default:l(()=>[...s[0]||(s[0]=[e("https://lists.mindrot.org/pipermail/openssh-unix-dev/2019-March/037672.html",-1)])]),_:1})])]),s[35]||(s[35]=o("<p>但是，大多數用户仍然更喜歡 SCP 協議。因為，SCP 處理遠程文件傳輸比同行 SFTP 和 Rsync 更快。</p><p>另外，SCP 的工作原理與 <code>cp</code> 命令完全相同，而 <code>rsync</code> 則會判斷源目錄是否有<strong>結尾斜槓</strong>而出現不同的行為。看一看下面的命令：</p><ul><li><code>rsync source destination/</code> - 將 <code>source</code> 目錄複製到 <code>destination</code> 文件夾內。</li><li><code>rsync source/ destination/</code> - 將 <code>source</code> 目錄的內容複製到 <code>destination</code> 文件夾中。</li></ul><p>所以，你必須反覆檢查是否在路徑中添加了斜槓。</p>",4)),i("p",null,[s[4]||(s[4]=e("我個人使用 ",-1)),i("strong",null,[a(t,{href:"https://ostechnix.com/linux-rsync-command-examples-for-beginners/"},{default:l(()=>[...s[3]||(s[3]=[e("Rsync",-1)])]),_:1})]),s[5]||(s[5]=e(" 在兩台主機之間複製大文件，使用 SCP 在網絡上覆制單個文件。",-1))]),s[36]||(s[36]=o('<h3 id="scp-命令語法" tabindex="-1">SCP 命令語法 <a class="header-anchor" href="#scp-命令語法" aria-label="Permalink to “SCP 命令語法”">​</a></h3><p>SCP 的通用語法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>scp [-346ABCpqrTv] [-c cipher] [-F ssh_config] [-i identity_file] [-J destination] [-l limit] [-o ssh_option] [-P port] [-S program] source ... target</span></span></code></pre></div><p>根據文件傳輸路徑的不同，語法也會有所不同。這裏我羅列了一些語法格式示例。</p><p>從本地複製一個文件到遠程系統：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>scp &lt;options&gt; SourceFile User@RemoteHost:RemotePath</span></span></code></pre></div><p>類似的，從本地系統複製一個目錄到遠程系統，使用 <code>-r</code> 參數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>scp -r SourceDirectory User@RemoteHost:RemotePath</span></span></code></pre></div><p>複製多個文件到遠程系統：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>scp &lt;options&gt; SourceFile1 SourceFile2 User@RemoteHost:RemotePath</span></span></code></pre></div><p>遠程系統複製文件到本地：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>scp &lt;options&gt; User@RemoteHost:RemoteFilePath DestinationFile</span></span></code></pre></div><p>遠程系統複製目錄到本地：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>scp -r User@RemoteHost:RemoteDirectoryPath DestinationDirectory</span></span></code></pre></div><p>在本地將文件在兩個遠程系統之間複製：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>scp &lt;options&gt; User@RemoteHost1:RemoteFile1 User@RemoteHost2:RemotePath</span></span></code></pre></div><p>注意，當你在兩個遠程系統之間複製文件時，流量不會通過本地系統。操作直接在兩個遠程系統之間進行。但是，你可以使用 <code>-3</code> 參數讓流量經過你運行 <code>scp</code> 命令的系統。</p><p>從你的本地系統將一個遠程系統的目錄複製到另一個遠程系統：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>scp -r User@RemoteHost1:RemoteDirectory User@RemoteHost2:DestinationPath</span></span></code></pre></div><h3 id="scp-命令參數" tabindex="-1">SCP 命令參數 <a class="header-anchor" href="#scp-命令參數" aria-label="Permalink to “SCP 命令參數”">​</a></h3><p>SCP 命令最常用的參數有：</p><ul><li><code>-C</code>：啓用壓縮。<code>C</code> 代表 <ruby>壓縮<rt>Compression</rt></ruby>。使用此參數時，數據傳輸速度會更快，因為數據是壓縮的。SCP 將自動在源系統上壓縮，並在目標系統上解壓縮。</li><li><code>-c &lt;cipher&gt;</code>：<code>c</code> 代表 <ruby>加密<rt>Cipher</rt></ruby>。默認情況下，SCP 使用 <strong>AES-128</strong> 加密方法對數據進行加密。你可以使用 <code>-c</code> 參數更改加密方法。</li><li><code>-i &lt;identity_file&gt;</code>：<code>i</code> 代表 <ruby>身份<rt>Identity</rt></ruby> 文件或私鑰。如你所知，SSH 中使用基於密碼或密鑰的身份驗證。如果希望在傳輸文件時使用基於密鑰的身份驗證，可以使用 <code>-i</code> 參數指定身份文件或私鑰。</li><li><code>-l limit</code>：<code>l</code> 代表 <ruby>限制<rt>Limit</rt></ruby> 帶寬。通過此參數，可以設置傳輸數據的最大帶寬。它的單位是 <code>Kbit/s</code>。</li><li><code>-F &lt;ssh_config&gt;</code>：有時你可能需要使用不同的網絡來連接到 Linux 系統，或你有一個代理服務器，這種情況下，你可以使用 <code>-F</code> 參數使用不同的 <code>ssh_config</code> <ruby>文件<rt>File</rt></ruby>。</li><li><code>-P port</code>：<code>P</code> 代表 <ruby>端口<rt>Port</rt></ruby>。注意，這是大寫的 <code>P</code>。默認情況下，SSH 使用端口 22。但出於安全原因，你可能已經更改了目標主機中的端口號。這種情況下，你應該使用 <code>-P</code> 參數顯示指定新端口號。</li><li><code>-p</code>：如果希望 <ruby>保留<rt>Preserve</rt></ruby> 原始文件的修改時間、訪問時間和模式，你需要使用 <code>-p</code> 參數。注意是小寫 <code>p</code>。</li><li><code>-r</code>：<ruby>遞歸<rt>Recursively</rt></ruby> 複製整個目錄。</li><li><code>-B</code>：<code>B</code> 代表 <ruby>批處理<rt>Batch</rt></ruby> 模式。它用於在傳輸文件時選擇批處理模式。可以防止詢問密碼。</li><li><code>-S program</code>：用於加密連接的 <ruby>程序<rt>Program</rt></ruby> 名稱。</li><li><code>-v</code>：<code>v</code> 代表 <ruby>詳細<rt>Verbose</rt></ruby>。當使用 <code>-v</code> 參數時，命令將會在終端屏幕上打印進度。你會看到文件傳輸時到底發生了什麼。它在調試連接、身份驗證和配置問題時非常有用。</li></ul><p>SCP 有很多參數，你可以查看它的手冊頁來了解其他參數。讓我們看一些<strong>有用的 scp 命令示例</strong>。</p><h3 id="開始前要記住的重要事項" tabindex="-1">開始前要記住的重要事項 <a class="header-anchor" href="#開始前要記住的重要事項" aria-label="Permalink to “開始前要記住的重要事項”">​</a></h3>',24)),i("ul",null,[s[11]||(s[11]=o("<li><code>scp</code> 命令依賴於 <code>ssh</code> 進行安全的文件傳輸。因此，你必須有一個 <strong>ssh 密鑰</strong>或<strong>密碼</strong>才能向遠程系統進行身份驗證。</li><li>為了能傳輸文件，你必須對<strong>源文件有讀權限</strong>，對<strong>目標位置有寫權限</strong>。</li><li><code>scp</code> 命令在寫入前不會檢查目標位置。目標位置中具有相同名稱的任何文件都將被<strong>覆蓋而不通知</strong>。</li><li>為了能夠區分本地和遠程位置，使用<strong>冒號</strong>（<code>:</code>）。</li>",4)),i("li",null,[s[8]||(s[8]=e("傳輸大文件時，建議在 ",-1)),i("strong",null,[a(t,{href:"https://ostechnix.com/screen-command-examples-to-manage-multiple-terminal-sessions/"},{default:l(()=>[...s[6]||(s[6]=[e("Screen",-1)])]),_:1})]),s[9]||(s[9]=e(" 或 ",-1)),i("strong",null,[a(t,{href:"https://ostechnix.com/tmux-command-examples-to-manage-multiple-terminal-sessions/"},{default:l(()=>[...s[7]||(s[7]=[e("Tmux",-1)])]),_:1})]),s[10]||(s[10]=e(" 會話內啓動任務。",-1))])]),s[37]||(s[37]=o(`<h3 id="在-linux-中使用-scp-傳輸文件" tabindex="-1">在 Linux 中使用 SCP 傳輸文件 <a class="header-anchor" href="#在-linux-中使用-scp-傳輸文件" aria-label="Permalink to “在 Linux 中使用 SCP 傳輸文件”">​</a></h3><p>正如我所説，我們可以使用 <code>scp</code> 命令將文件或目錄從本地複製到遠程系統，反之亦然，或者在兩台遠程系統之間複製文件或目錄。</p><h4 id="_1-使用-scp-從本地系統複製文件到遠程系統" tabindex="-1">1. 使用 SCP 從本地系統複製文件到遠程系統 <a class="header-anchor" href="#_1-使用-scp-從本地系統複製文件到遠程系統" aria-label="Permalink to “1. 使用 SCP 從本地系統複製文件到遠程系統”">​</a></h4><p>使用 <code>scp</code> 命令將文件從本地複製到遠程系統，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ scp File1.txt ostechnix@192.168.1.40:/home/ostechnix/</span></span></code></pre></div><p>示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ostechnix@192.168.1.40&#39;s password: </span></span>
<span class="line"><span>File1.txt                                                    100%  104   814.0KB/s   00:00</span></span></code></pre></div><p>讓我們分析一下上面的命令，看看每個參數都做了什麼。</p><ul><li><code>File1.txt</code> - 源文件</li><li><code>ostechnix</code> - 遠程系統的用户名</li><li><code>192.168.1.40</code> - 遠程系統的 IP 地址</li><li><code>/home/ostechnix/</code> - 遠程系統中的目標目錄。這是我們想要傳輸源文件的絕對路徑，如 <code>File.txt</code>。</li></ul><p>你還可以修改目標文件的名稱。下面的命令將 <code>File1.txt</code> 傳輸到目的地，保存為 <code>myfile.txt</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ scp File1.txt ostechnix@192.168.1.40:/home/ostechnix/myfile.txt</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2022/11/Copy-Files-from-Local-System-to-Remote-System.png" alt="將文件從本地複製到遠程系統"></p><h4 id="_2-使用-scp-從本地系統複製多個文件到遠程系統" tabindex="-1">2. 使用 SCP 從本地系統複製多個文件到遠程系統 <a class="header-anchor" href="#_2-使用-scp-從本地系統複製多個文件到遠程系統" aria-label="Permalink to “2. 使用 SCP 從本地系統複製多個文件到遠程系統”">​</a></h4><p>使用 <code>scp</code> 命令將多個文件從本地系統傳輸到遠程系統，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ scp File1.txt File2.txt ostechnix@192.168.1.40:/home/ostechnix/</span></span></code></pre></div><p>示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ostechnix@192.168.1.40&#39;s password: </span></span>
<span class="line"><span>File1.txt                                                    100%  104   689.4KB/s   00:00    </span></span>
<span class="line"><span>File2.txt                                                    100%  496     6.3MB/s   00:00</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2022/11/Copy-Multiple-Files-from-Local-System-to-Remote-System.png" alt="從本地複製多個文件到遠程系統"></p><p>這裏：</p><ul><li><code>File1.txt</code> 和 <code>File2.txt</code> - 源文件名</li><li><code>ostechnix@192.168.1.40</code> - 遠程系統的用户名和 IP 地址</li><li><code>/home/ostechnix</code> - 目標文件的路徑</li></ul><p>如果文件具有相同的擴展名，你可以使用以下替代命令來實現相同的目標。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ scp {File1,File2}.txt ostechnix@192.168.1.40:/home/ostechnix/</span></span></code></pre></div><p>或者，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ scp *.txt ostechnix@192.168.1.40:/home/ostechnix/</span></span></code></pre></div><h4 id="_3-使用-scp-從本地到遠程系統遞歸複製目錄" tabindex="-1">3. 使用 SCP 從本地到遠程系統遞歸複製目錄 <a class="header-anchor" href="#_3-使用-scp-從本地到遠程系統遞歸複製目錄" aria-label="Permalink to “3. 使用 SCP 從本地到遠程系統遞歸複製目錄”">​</a></h4><p>遞歸地將整個目錄（包括子目錄及其內容）從本地複製到遠程系統，使用 <code>-r</code> 參數。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ scp -r Documents/ ostechnix@192.168.1.40:/home/ostechnix/</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2022/11/Copy-Directory-from-Local-System-to-Remote-System.png" alt="從本地複製目錄到遠程系統"></p><p>上述命令將整個 <code>Documents</code> 目錄包括其內容複製到目標系統。</p><p>其中，</p><ul><li><code>-r</code> - 遞歸複製文件和目錄，包括子目錄及其內容</li><li><code>Documents</code> - 源目錄名稱</li><li><code>ostechnix@192.168.1.40</code> - 遠程系統的用户名和 IP 地址</li><li><code>/home/ostechnix</code> - 目標目錄的路徑</li></ul><h4 id="_4-用-scp-將文件從遠程系統傳輸到本地" tabindex="-1">4. 用 SCP 將文件從遠程系統傳輸到本地 <a class="header-anchor" href="#_4-用-scp-將文件從遠程系統傳輸到本地" aria-label="Permalink to “4. 用 SCP 將文件從遠程系統傳輸到本地”">​</a></h4><p>還記得我們從本地系統複製了 <code>File1.txt</code> 到遠程系統，讓我們把它複製回本地。</p><p>使用 <code>scp</code> 命令從遠程系統複製文件到本地，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ scp ostechnix@192.168.1.40:/home/ostechnix/File1.txt Downloads/</span></span></code></pre></div><p>其中</p><ul><li><code>ostechnix@192.168.1.40</code> - 遠程系統的用户名和 IP 地址</li><li><code>/home/ostechnix/File.txt</code> - 遠程系統文件的絕對路徑</li><li><code>Downloads</code> - 本地保存複製文件的位置</li></ul><p><img src="https://ostechnix.com/wp-content/uploads/2022/11/Transfer-Files-from-Remote-System-to-Local-System.png" alt="從遠程系統傳輸文件到本地"></p><h4 id="_5-使用-scp-將多個文件從遠程系統傳輸到本地" tabindex="-1">5. 使用 SCP 將多個文件從遠程系統傳輸到本地 <a class="header-anchor" href="#_5-使用-scp-將多個文件從遠程系統傳輸到本地" aria-label="Permalink to “5. 使用 SCP 將多個文件從遠程系統傳輸到本地”">​</a></h4><p>將多個文件從遠程系統複製到本地，在<strong>花括號內</strong>註明文件的絕對路徑，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ scp ostechnix@192.168.1.40:/home/ostechnix/\\{File1.txt,File2.txt\\} Downloads/</span></span></code></pre></div><p><img src="https://ostechnix.com/wp-content/uploads/2022/11/Transfer-Multiple-Files-from-Remote-System-to-Local-System.png" alt="將多個文件從遠程系統傳輸到本地"></p><p>上述命令將從遠程系統的 <code>/home/ostechnix/</code> 目錄中複製 <code>File1.txt</code> 和 <code>File2.txt</code> 到本地的 <code>Downloads</code> 目錄中。</p><p>注意，<strong>花括號內的逗號後面沒有空格</strong>。</p><h4 id="_6-從遠程系統遞歸複製目錄到本地" tabindex="-1">6. 從遠程系統遞歸複製目錄到本地 <a class="header-anchor" href="#_6-從遠程系統遞歸複製目錄到本地" aria-label="Permalink to “6. 從遠程系統遞歸複製目錄到本地”">​</a></h4><p>使用 <code>scp</code> 從遠程系統遞歸複製整個目錄（包括子目錄及其內容）到本地系統，使用 <code>-r</code> 參數。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ scp -r ostechnix@192.168.1.40:/home/ostechnix/Documents Downloads/</span></span></code></pre></div><p>上述命令將從遠程系統將整個 <code>Documents</code> 目錄複製到本地的 <code>Downloads</code> 目錄。</p><h4 id="_7-使用-scp-在兩台遠程計算機之間複製文件" tabindex="-1">7. 使用 SCP 在兩台遠程計算機之間複製文件 <a class="header-anchor" href="#_7-使用-scp-在兩台遠程計算機之間複製文件" aria-label="Permalink to “7. 使用 SCP 在兩台遠程計算機之間複製文件”">​</a></h4><p>使用 <code>scp</code> 命令將文件從一個遠程系統直接複製到另一個遠程系統，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ scp senthil@192.168.1.40:/home/senthil/File1.txt kumar@192.168.1.20:/home/kumar/</span></span></code></pre></div><p>它會要求你輸入兩個遠程系統的密碼：</p><p>其中，</p><ul><li><code>senthil@192.168.1.40</code> - 文件源端遠程系統的用户名和 IP 地址</li><li><code>/home/senthil/File1.txt</code> - 複製的文件名及其位置</li><li><code>kumar@192.168.1.20</code> - 複製文件到目標端的用户名和 IP 地址</li><li><code>/home/kumar</code> - 在目標端上保存複製文件的位置</li></ul><p>上述命令將從遠程主機 <code>192.168.1.40</code> 複製 <code>/home/senthil/File1.txt</code> 到 <code>192.168.1.20</code> 上的 <code>/home/kumar/</code> 目錄。</p><p>在這種方法中，數據將直接從一個遠程系統傳輸到另一個遠程系統。如果你想通過本地機器路由流量，使用 <code>-3</code> 參數，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ scp -3 senthil@192.168.1.40:/home/senthil/File1.txt kumar@192.168.1.20:/home/kumar/</span></span></code></pre></div><h4 id="_8-使用-scp-複製文件時啓用壓縮" tabindex="-1">8. 使用 SCP 複製文件時啓用壓縮 <a class="header-anchor" href="#_8-使用-scp-複製文件時啓用壓縮" aria-label="Permalink to “8. 使用 SCP 複製文件時啓用壓縮”">​</a></h4><p>到目前為止，我們在沒有壓縮的情況下傳輸了文件。現在我們將使用 <code>-C</code> 參數在傳輸文件時啓用壓縮。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ scp -C File1.txt ostechnix@192.168.1.40:/home/ostechnix/</span></span></code></pre></div><p><code>-C</code> 參數將在源端啓用壓縮，並在目標端自動解壓數據。</p><p>通過啓用壓縮，可以顯著提高文件複製或傳輸速度。</p><h4 id="_9-使用-scp-傳輸文件時限制帶寬" tabindex="-1">9. 使用 SCP 傳輸文件時限制帶寬 <a class="header-anchor" href="#_9-使用-scp-傳輸文件時限制帶寬" aria-label="Permalink to “9. 使用 SCP 傳輸文件時限制帶寬”">​</a></h4><p>我們可以使用 <code>-l</code> 參數限制帶寬。注意，最大帶寬單位為 Kbits/s。1 Byte = 8 bit。因此，如果你想將帶寬限制在 200KB/s，<code>-l</code> 的值將是 <strong>1600</strong>（200*8）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ scp -l 1600 File1.txt ostechnix@192.168.1.40:/home/ostechnix/</span></span></code></pre></div><p>這在傳輸大文件時非常有用，可以防止 SCP 限制帶寬。</p><h4 id="_10-使用-scp-複製文件時使用不同端口" tabindex="-1">10. 使用 SCP 複製文件時使用不同端口 <a class="header-anchor" href="#_10-使用-scp-複製文件時使用不同端口" aria-label="Permalink to “10. 使用 SCP 複製文件時使用不同端口”">​</a></h4>`,67)),i("p",null,[s[13]||(s[13]=e("作為系統管理員，出於安全原因，你可能在遠程服務器上 ",-1)),a(t,{href:"https://ostechnix.com/how-to-change-apache-ftp-and-ssh-default-port-to-a-custom-port-part-3/"},{default:l(()=>[...s[12]||(s[12]=[e("更改了 SSH 協議的默認端口",-1)])]),_:1}),s[14]||(s[14]=e("。這種情況下，你可以在傳輸文件時使用 ",-1)),s[15]||(s[15]=i("code",null,"-P",-1)),s[16]||(s[16]=e(" 參數指定端口號。注意：大寫的 ",-1)),s[17]||(s[17]=i("code",null,"P",-1)),s[18]||(s[18]=e("。",-1))]),s[38]||(s[38]=o(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ scp -P 2022 File1.txt ostechnix@192.168.1.40:/home/ostechnix/</span></span></code></pre></div><h4 id="_11-使用-scp-複製文件時使用不同的加密方法" tabindex="-1">11. 使用 SCP 複製文件時使用不同的加密方法 <a class="header-anchor" href="#_11-使用-scp-複製文件時使用不同的加密方法" aria-label="Permalink to “11. 使用 SCP 複製文件時使用不同的加密方法”">​</a></h4><p>默認情況下，SCP 使用 <code>AES-128</code> 對文件進行加密。如果你想使用不同的加密方法，使用 <code>c</code> 參數。</p><p>例如，如果你想使用 <strong>3des-cbc</strong> 加密方法，命令如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ scp -c 3des-cbc File1.txt ostechnix@192.168.1.40:/home/ostechnix/</span></span></code></pre></div><p>要查看支持的密碼列表，執行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh -Q cipher localhost | paste -d, -s -</span></span></code></pre></div><p>示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>3des-cbc,aes128-cbc,aes192-cbc,aes256-cbc,rijndael-cbc@lysator.liu.se,aes128-ctr,aes192-ctr,aes256-ctr,aes128-gcm@openssh.com,aes256-gcm@openssh.com,chacha20-poly1305@openssh.com</span></span></code></pre></div><h4 id="_12-在詳細模式下使用-scp-複製文件" tabindex="-1">12. 在詳細模式下使用 SCP 複製文件 <a class="header-anchor" href="#_12-在詳細模式下使用-scp-複製文件" aria-label="Permalink to “12. 在詳細模式下使用 SCP 複製文件”">​</a></h4><p>如果你想知道使用 <code>scp</code> 複製文件時幕後發生了什麼，你可以使用 <code>-v</code> 參數。使用詳細模式傳輸文件時，終端上會顯示執行 <code>scp</code> 命令執行的每一步過程。這在故障排除時很方便。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ scp -v File1.txt ostechnix@192.168.1.40:/home/ostechnix/</span></span></code></pre></div><p>在詳細模式下發送文件時，你將看到大量輸出，如下所示：</p><p><img src="https://ostechnix.com/wp-content/uploads/2022/11/Copying-Files-with-SCP-in-Verbose-Mode.png" alt="在詳細模式下使用 SCP 複製文件"></p><h4 id="_13-在安靜模式下使用-scp-傳輸文件" tabindex="-1">13. 在安靜模式下使用 SCP 傳輸文件 <a class="header-anchor" href="#_13-在安靜模式下使用-scp-傳輸文件" aria-label="Permalink to “13. 在安靜模式下使用 SCP 傳輸文件”">​</a></h4><p>我們可以使用 <code>-q</code> 參數在安靜模式下傳輸文件。在安靜模式下共享文件時，不會在輸出中顯示進度、警告或診斷信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ scp -q File1.txt ostechnix@192.168.1.40:/home/ostechnix/</span></span></code></pre></div><h4 id="_14-使用-scp-傳輸文件時保留文件屬性" tabindex="-1">14. 使用 SCP 傳輸文件時保留文件屬性 <a class="header-anchor" href="#_14-使用-scp-傳輸文件時保留文件屬性" aria-label="Permalink to “14. 使用 SCP 傳輸文件時保留文件屬性”">​</a></h4><p>使用 <code>-p</code> 參數可以保留文件修改時間、訪問時間和模式等文件屬性。注意，這是<strong>小寫的 p</strong>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ scp -p File1.txt ostechnix@192.168.1.40:/home/ostechnix/</span></span></code></pre></div><h4 id="_15-使用-scp-複製文件時使用身份文件" tabindex="-1">15. 使用 SCP 複製文件時使用身份文件 <a class="header-anchor" href="#_15-使用-scp-複製文件時使用身份文件" aria-label="Permalink to “15. 使用 SCP 複製文件時使用身份文件”">​</a></h4><p>SSH 同時支持基於密碼和密鑰的身份驗證。密鑰是 Linux 環境中使用最廣泛的身份驗證方法。</p><p>如果你想在傳輸文件時使用基於密鑰的身份驗證，使用 <code>-i</code> 參數指定身份文件或私鑰。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ scp -i my_private_key.pem File1.txt ostechnix@192.168.1.40:/home/ostechnix/</span></span></code></pre></div><h4 id="_16-使用不同的-ssh-配置文件" tabindex="-1">16. 使用不同的 ssh 配置文件 <a class="header-anchor" href="#_16-使用不同的-ssh-配置文件" aria-label="Permalink to “16. 使用不同的 ssh 配置文件”">​</a></h4><p>在某些情況下，你需要使用不同的網絡來連接到 Linux 系統，或你有一個代理服務器。這在情況下，你可以配合 <code>-F</code> 參數使用不同的 <code>ssh_config</code> 文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ scp -F /home/ostechnix/my_ssh_config File1.txt ostechnix@192.168.1.40:/home/ostechnix/</span></span></code></pre></div><h4 id="_17-使用-ipv4-或-ipv6-複製文件" tabindex="-1">17. 使用 IPv4 或 IPv6 複製文件 <a class="header-anchor" href="#_17-使用-ipv4-或-ipv6-複製文件" aria-label="Permalink to “17. 使用 IPv4 或 IPv6 複製文件”">​</a></h4><p>在複製文件時，我們可以強制 SCP 只使用 IPv4 或 IPv6 地址。IPv4 網絡添加 <code>-4</code> 參數，IPv6 網絡添加 <code>-6</code> 參數可以實現這一點。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ scp -6 File1.txt ostechnix@192.168.1.40:/home/ostechnix/</span></span></code></pre></div><h3 id="常見問題" tabindex="-1">常見問題 <a class="header-anchor" href="#常見問題" aria-label="Permalink to “常見問題”">​</a></h3><h4 id="問題-1-什麼是-scp" tabindex="-1">問題 1：什麼是 SCP？ <a class="header-anchor" href="#問題-1-什麼是-scp" aria-label="Permalink to “問題 1：什麼是 SCP？”">​</a></h4><p>SCP 是一個命令列程序，旨在將文件和目錄從本地系統安全地傳輸到遠程系統，反之亦然，或者直接在兩個遠程系統之間傳輸。</p><h4 id="問題-2-如何使用-scp-將文件從本地複製到遠程計算機" tabindex="-1">問題 2: 如何使用 SCP 將文件從本地複製到遠程計算機？ <a class="header-anchor" href="#問題-2-如何使用-scp-將文件從本地複製到遠程計算機" aria-label="Permalink to “問題 2: 如何使用 SCP 將文件從本地複製到遠程計算機？”">​</a></h4><p>將文件從本地複製到遠程系統，命令如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>scp SourceFile.txt User@RemoteHost:/some/remote/directory</span></span></code></pre></div><h4 id="問題-3-如何遞歸複製文件和目錄" tabindex="-1">問題 3：如何遞歸複製文件和目錄？ <a class="header-anchor" href="#問題-3-如何遞歸複製文件和目錄" aria-label="Permalink to “問題 3：如何遞歸複製文件和目錄？”">​</a></h4><p>遞歸複製包含子目錄的目錄，使用 <code>-r</code> 參數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>scp -r /some/local/directory User@RemoteHost:/some/remote/directory</span></span></code></pre></div><h4 id="問題-4-使用-scp-可以傳輸多個文件嗎" tabindex="-1">問題 4：使用 SCP 可以傳輸多個文件嗎？ <a class="header-anchor" href="#問題-4-使用-scp-可以傳輸多個文件嗎" aria-label="Permalink to “問題 4：使用 SCP 可以傳輸多個文件嗎？”">​</a></h4><p>當然，只要用空格分隔源文件名即可。</p><p>從本地複製多個文件到遠程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>scp file1.txt file2.txt file3.txt User@RemoteHost:/some/remote/directory</span></span>
<span class="line"><span>scp {file1,file2,file3}.txt User@RemoteHost:/some/remote/directory</span></span>
<span class="line"><span>scp *.txt User@RemoteHost:/some/remote/directory</span></span></code></pre></div><p>從遠程複製多個文件到本地：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>scp User@RemoteHost:/some/remote/directory/\\{file1.txt,file2.txt,file3.txt\\} /some/local/directory</span></span></code></pre></div><p>從一個遠程系統複製多個文件到另一個遠程系統：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ scp User@RemoteHost1:/some/remote/directory/\\{file1.txt,file2.txt,file3.txt\\} User@RemoteHost2:/some/remote/directory/</span></span></code></pre></div><h4 id="問題-5-如何傳輸目錄下的所有文件" tabindex="-1">問題 5：如何傳輸目錄下的所有文件？ <a class="header-anchor" href="#問題-5-如何傳輸目錄下的所有文件" aria-label="Permalink to “問題 5：如何傳輸目錄下的所有文件？”">​</a></h4><p>傳輸整個目錄，首先進入該目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd dir_name</span></span></code></pre></div><p>然後，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>scp *.txt User@RemoteHost:/some/remote/directory</span></span></code></pre></div><h4 id="問題-6-可以壓縮文件嗎" tabindex="-1">問題 6：可以壓縮文件嗎？ <a class="header-anchor" href="#問題-6-可以壓縮文件嗎" aria-label="Permalink to “問題 6：可以壓縮文件嗎？”">​</a></h4><p>當然。使用 <code>-C</code> 壓縮文件。文件會在源端壓縮，在目標端自動解壓縮。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>scp -C /some/large/file User@RemoteHost:/some/remote/directory</span></span></code></pre></div><h4 id="問題-7-可以保留文件屬性嗎" tabindex="-1">問題 7：可以保留文件屬性嗎？ <a class="header-anchor" href="#問題-7-可以保留文件屬性嗎" aria-label="Permalink to “問題 7：可以保留文件屬性嗎？”">​</a></h4><p>保留原始文件的修改時間、訪問時間和模式等文件屬性，使用 <code>-p</code> 參數。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>scp -p file.txt User@RemoteHost:/some/remote/directory</span></span></code></pre></div><h4 id="問題-8-可以使用其他端口嗎" tabindex="-1">問題 8: 可以使用其他端口嗎？ <a class="header-anchor" href="#問題-8-可以使用其他端口嗎" aria-label="Permalink to “問題 8: 可以使用其他端口嗎？”">​</a></h4><p>當然。SCP 配合 <code>-P</code> 參數允許你使用其他端口。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>scp -P 2022 file.txt User@RemoteHost:/some/remote/directory</span></span></code></pre></div><h4 id="問題-9-可以使用不同的加密方法嗎" tabindex="-1">問題 9: 可以使用不同的加密方法嗎？ <a class="header-anchor" href="#問題-9-可以使用不同的加密方法嗎" aria-label="Permalink to “問題 9: 可以使用不同的加密方法嗎？”">​</a></h4><p>當然。使用 <code>-c</code> 參數。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>scp -c 3des-cbc User@RemoteHost:/some/remote/directory</span></span></code></pre></div><h4 id="問題-10-如何列出-ssh-支持的加密方法" tabindex="-1">問題 10: 如何列出 SSH 支持的加密方法？ <a class="header-anchor" href="#問題-10-如何列出-ssh-支持的加密方法" aria-label="Permalink to “問題 10: 如何列出 SSH 支持的加密方法？”">​</a></h4><p>使用以下命令查看 SSH 和 SCP 支持的加密方法列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ssh -Q cipher localhost | paste -d, -s -</span></span></code></pre></div><h4 id="問題-11-scp-真的安全嗎" tabindex="-1">問題 11：SCP 真的安全嗎？ <a class="header-anchor" href="#問題-11-scp-真的安全嗎" aria-label="Permalink to “問題 11：SCP 真的安全嗎？”">​</a></h4><p>當然，它用起來是完全安全的。SCP 和 openSSH 使用相同的 SSH 機制。傳輸的數據在源端加密，目標端解密。</p><h4 id="問題-12-可以從-windows-系統傳輸文件到-linux-嗎" tabindex="-1">問題 12：可以從 Windows 系統傳輸文件到 Linux 嗎？ <a class="header-anchor" href="#問題-12-可以從-windows-系統傳輸文件到-linux-嗎" aria-label="Permalink to “問題 12：可以從 Windows 系統傳輸文件到 Linux 嗎？”">​</a></h4><p>當然。使用 <code>PSCP</code> 程序將文件從 windows 傳輸到 Linux 平台，你也可以使用 <code>WinSCP</code>。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>在這篇全面指南中，我們瞭解了什麼是 SCP，以及如何在 Linux 中使用 <strong>SCP 安全地傳輸文件</strong>，其中包括 <strong>17 個 SCP 命令示例</strong>，另外還回答了關於 SCP 的常見問題。</p><p>無論你是 Linux 管理人員、開發人員還是普通用户，你都會面臨某個時候將文件複製到遠程系統或從遠程系統複製文件的情況，知道如何<strong>使用 SCP 安全地複製文件</strong>將是非常有用的。</p><hr>`,75)),i("p",null,[s[20]||(s[20]=e("via: ",-1)),a(t,{href:"https://ostechnix.com/securely-transfer-files-with-scp-in-linux/"},{default:l(()=>[...s[19]||(s[19]=[e("https://ostechnix.com/securely-transfer-files-with-scp-in-linux/",-1)])]),_:1})]),i("p",null,[s[25]||(s[25]=e("作者：",-1)),a(t,{href:"https://ostechnix.com/author/sk/"},{default:l(()=>[...s[21]||(s[21]=[e("sk",-1)])]),_:1}),s[26]||(s[26]=e(" 選題：",-1)),a(t,{href:"https://github.com/lkxed"},{default:l(()=>[...s[22]||(s[22]=[e("lkxed",-1)])]),_:1}),s[27]||(s[27]=e(" 譯者：",-1)),a(t,{href:"https://github.com/MjSeven"},{default:l(()=>[...s[23]||(s[23]=[e("MjSeven",-1)])]),_:1}),s[28]||(s[28]=e(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:l(()=>[...s[24]||(s[24]=[e("wxy",-1)])]),_:1})]),i("p",null,[s[31]||(s[31]=e("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[29]||(s[29]=[e("LCTT",-1)])]),_:1}),s[32]||(s[32]=e(" 原創編譯，",-1)),a(t,{href:"https://linux.cn/"},{default:l(()=>[...s[30]||(s[30]=[e("Linux中國",-1)])]),_:1}),s[33]||(s[33]=e(" 榮譽推出",-1))])])}const C=n(h,[["render",r]]);export{y as __pageData,C as default};
